/**
 * Turning a request into a signed plan.
 *
 * The plan is generated by an explicit model call rather than inferred from
 * whatever tools the first turn happens to use, so the agent has to state what it
 * is going to do before it does anything.
 */
import type { IntentPlan, PlanStep } from "@picto/agent-core";
import { toolByName } from "../mcps/registry.js";
import { chat } from "./llm.js";
import { PLANNER_PROMPT } from "./prompts.js";

/**
 * The charter of any run.
 *
 * Reading, writing, branching and publishing a branch are the ordinary
 * capabilities of a coding agent. Declaring them for every run is the operator's
 * decision about what this agent is for, not the model's - and it means a plan is
 * always a workable plan, instead of one that blocks the agent halfway through a
 * task because the model forgot to predict a step.
 *
 * `git_branch` is here for the same reason `run_command` is not. Creating a branch
 * is one reversible act with a name, so it can be granted on its own; the model
 * that wanted a branch and did not have one reached for the shell instead, which
 * turned the most ordinary step of the task into an interruption for a human. The
 * narrow tool is the thing that keeps the shell's absence from being a cost.
 *
 * `run_command` is deliberately NOT in this list. ArmorIQ matches a plan on tool
 * NAMES, not arguments, so declaring a generic shell declares everything that
 * shell could ever be asked to do. A shell's surface is the whole machine, and
 * an allow list that grants it is not saying anything useful. See
 * NEVER_AUTO_DECLARED.
 */
const BASELINE = [
  "list_files",
  "read_file",
  "write_file",
  "git_branch",
  "git_commit",
  "push_branch",
];

/**
 * Capabilities that are never declared automatically, however they are asked
 * for.
 *
 * Both are actions a maintainer cannot undo by closing a pull request:
 *
 *   push_main     writes to the default branch, which everyone else is building
 *                 on. It is the one publish that review cannot catch.
 *
 *   run_command   is a shell. Because a plan is matched on tool names alone,
 *                 allowing this single name allows every command it could be
 *                 given - including ones nobody predicted. Its surface is the
 *                 machine, not the change.
 *
 * Keeping them out of every plan means the agent cannot reach either on its own:
 * the call will not match the signed plan, ArmorIQ refuses it, and the only way
 * forward is a fresh plan that a human approved.
 */
const NEVER_AUTO_DECLARED = new Set(["push_main", "run_command"]);

export interface PlannedIntent extends IntentPlan {
  /** Steps the model asked for that we refused to auto-declare. */
  refused: string[];
  /** Steps the model asked for that are not real tools. */
  unknown: string[];
}

function extractJson(text: string): unknown {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced?.[1] ?? text;
  const start = candidate.indexOf("{");
  const end = candidate.lastIndexOf("}");
  if (start === -1 || end === -1) {
    throw new Error(`planner did not return JSON: ${text.slice(0, 200)}`);
  }
  return JSON.parse(candidate.slice(start, end + 1));
}

/**
 * Pull the tool names out of a response that was cut off mid-JSON.
 *
 * A truncated plan is still a usable declaration of intent - the action names
 * are what the plan is built from, and they appear before the reasons that
 * overran the budget. Falling back to the baseline plan here would quietly throw
 * away everything the model actually asked for.
 */
function actionsFromTruncated(text: string): string[] {
  const found: string[] = [];
  for (const match of text.matchAll(/"action"\s*:\s*"([^"]+)"/g)) {
    if (match[1]) found.push(match[1]);
  }
  return found;
}

export async function planFromPrompt(input: {
  instruction: string;
  repo: string;
}): Promise<PlannedIntent> {
  const message = await chat({
    messages: [
      { role: "system", content: PLANNER_PROMPT },
      { role: "user", content: `REPOSITORY\n${input.repo}\n\nTASK\n${input.instruction}` },
    ],
    temperature: 0.2,
    maxTokens: 1500,
  });

  let goal = `Work on ${input.repo}`;
  const requested: Array<{ action: string; reason?: string }> = [];
  const raw = message.content ?? "";

  try {
    const parsed = extractJson(raw) as {
      goal?: string;
      steps?: Array<{ action?: string; reason?: string }>;
    };
    if (typeof parsed.goal === "string" && parsed.goal.trim()) goal = parsed.goal.trim();
    for (const step of parsed.steps ?? []) {
      if (typeof step?.action === "string") {
        requested.push({ action: step.action, reason: step.reason });
      }
    }
  } catch {
    const salvaged = actionsFromTruncated(raw);
    for (const action of salvaged) requested.push({ action });
    console.warn(
      `[planner] response was not complete JSON; recovered ${salvaged.length} step(s) from it`,
    );
  }

  const refused: string[] = [];
  const unknown: string[] = [];
  const steps: PlanStep[] = [];
  const seen = new Set<string>();

  const add = (name: string, reason?: string): void => {
    if (seen.has(name)) return;
    const def = toolByName(name);
    if (!def) {
      unknown.push(name);
      return;
    }
    if (NEVER_AUTO_DECLARED.has(name)) {
      refused.push(name);
      return;
    }
    seen.add(name);
    steps.push({ action: name, mcp: def.mcp, params: {}, description: reason ?? def.title });
  };

  for (const name of BASELINE) add(name, "ordinary work for this agent");
  for (const step of requested) add(step.action, step.reason);

  return { goal, steps, refused, unknown };
}
